"use client"
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { Activity, BarChart3, Layers, Sparkles } from 'lucide-react'

interface ExperientialTabsProps {
  activeTab: 'catalogs' | 'activities' | 'reports' | 'themes'
}

export function ExperientialTabs({ activeTab }: ExperientialTabsProps) {
  const pathname = usePathname() || ''
  const isAdmin = pathname.startsWith('/admin')

  const tabs = [
    { 
      id: 'catalogs', 
      label: 'Danh mục HĐTN & Ngoại khóa', 
      href: '/admin/experiential-activities/catalogs', 
      icon: Layers 
    },
    { 
      id: 'themes', 
      label: 'Chủ đề giáo dục', 
      href: '/admin/experiential-activities/catalogs?tab=themes', 
      icon: Sparkles 
    },
    { 
      id: 'activities', 
      label: 'Quản lý Triển khai & Đánh giá', 
      href: isAdmin ? '/admin/experiential-activities' : '/teacher/experiential-activities', 
      icon: Activity 
    },
    { 
      id: 'reports', 
      label: 'Dashboard Giám sát Tiến độ', 
      href: '/admin/experiential-activities/reports', 
      icon: BarChart3 
    }
  ]

  return (
    <div className="space-y-4 mb-6 no-print font-sans">
      <div className="bg-white border border-slate-200/80 shadow-xs rounded-2xl p-1.5 backdrop-blur-md">
        <div className="flex flex-wrap gap-1.5">
          {tabs.map((tab) => {
            const isActive = activeTab === tab.id
            const Icon = tab.icon
            return (
              <Link
                key={tab.id}
                href={tab.href}
                className={"flex items-center gap-2 px-5 py-2.5 rounded-xl text-xs font-medium transition-all duration-200 border " + (
                  isActive
                    ? 'bg-gradient-to-r from-[#003B3A] to-[#00A19A] text-white border-transparent shadow-md shadow-[#00A19A]/20'
                    : 'text-slate-600 border-transparent hover:bg-slate-50 hover:text-slate-900'
                )}
              >
                <Icon className={"w-4 h-4 " + (isActive ? 'text-white' : 'text-slate-400')} />
                <span>{tab.label}</span>
              </Link>
            )
          })}
        </div>
      </div>
    </div>
  )
}
